import React, { useEffect, useState } from 'react';

import axios from 'axios';

import Summary from './summary.js';
import Experience from './exp.js';
import Education from './education';
import Projects from './Projects'


let summary = require("./json/summary.json");

function replaceEY(node, value) {
    if (typeof node === 'string') {
        if (node === '{{EY}}') return value;
        return node.replace(/{{EY}}/g, String(value));
    }
    if (Array.isArray(node)) return node.map(n => replaceEY(n, value));
    if (node && typeof node === 'object') {
        const out = {};
        for (const k in node) out[k] = replaceEY(node[k], value);
        return out;
    }
    return node;
}

summary = replaceEY(summary, require("./json/experience.json"));
const education = require("./json/edu.json")
const experience = require("./json/exp.json")
const projects = require("./json/proj.json")
const totalExperience = require("./json/experience.json")

const Tabs = () => {
    const [data, setData] = useState({});
    const [type, setType] = useState("Doughnut");
    const [tab, setTab] = useState("Summary");
  
    useEffect(() => {
        const TabJSON = {
            Summary: summary,
            Education: education,
            Experience: experience,
            Projects: projects,
        }[tab];

        setData(TabJSON);

    }, [tab]);

 return (
        <div className="flex-container-fluid">
            <div className="d-flex" style={{ flexDirection: "column" }} >

                <div className="d-flex" >
                    <div className="d-flex p-2" style={{
                        backgroundColor: tab === "Summary" ? "#dbe8ec" : "#ffffff"
                    }}
                        onClick={e => {
                            setType("Doughnut")
                            setTab("Summary")
                        }}
                    >
                        <div className="icon px-2">
                            <i className="fa fa-laptop fa-1x" style={{ color: "#999999" }}></i>
                        </div>
                        <div>
                            <label> Summary </label>
                        </div>
                    </div>


                    <div className="p-2 pl-4 pr-4 d-flex justify-content-center" style={{
                        backgroundColor: tab === "Education" ? "#dbe8ec" : "#ffffff"
                    }}
                        onClick={() => {
                            setTab("Education")
                        }}>
                        <div>
                            <i className="fa fa-book fa-1x" style={{ color: "#999999" }}></i>
                        </div>

                        <div className="icon px-2">
                            <label> Education </label>
                        </div>
                    </div>

                    <div className=" p-2 pl-4 pr-4 d-flex justify-content-center" style={{
                        backgroundColor: tab === "Experience" ? "#dbe8ec" : "#ffffff"
                    }}
                        onClick={() => {
                            setType("Doughnut")
                            setTab("Experience")
                        }}>
                        <div className="icon px-2">
                            <i className="fa fa-laptop fa-1x" style={{ color: "#999999" }}></i>
                        </div>
                        <div>
                            <label> Experience </label>
                        </div>
                    </div>


                    <div className="p-2 pl-4 pr-4 d-flex" style={{
                        backgroundColor: tab === "Projects" ? "#dbe8ec" : "#ffffff"
                    }}
                        onClick={() => {
                            setTab("Projects")
                        }}>
                        <div className="icon px-2">
                            <i className="fa fa-tasks fa-1x" style={{ color: "#999999" }}></i>
                        </div>

                        <div>
                            <label> Projects </label>
                        </div>

                    </div>
                 
                </div>


                <div className="flex-container-fluid" >
                    <div style={{ backgroundColor: "#dbe8ec" }}>
                        {
                            tab === "Summary" &&
                            <Summary
                                data={data}
                                type={type}
                            />
                        }
                        {
                            tab === "Experience" &&
                            <Experience
                                timeline={data.timeline}
                                chart={data.chart}
                                type={type}
                                description={data.description && data.description}
                            />

                        }

                        {
                            tab === "Education" &&
                            <Education
                                description={data.description && data.description}
                                certification={data.certification && data.certification}
                                technologies={data.technologies && data.technologies}
                            />

                        }

                        {
                            tab === "Projects" &&
                            <Projects
                                projects={data.projects && data.projects}
                            />

                        }
                    </div>
                </div>
            </div>
        </div>

    )
}

export default Tabs