import React, { Component } from 'react';

import Chart from "./lib/chart"
import ChartLegends from "./lib/chartLegends"
import PieChartLegends from "./lib/pieChartLegends"
import ReChart from './lib/pieChart';
import Points from "./points.js"
import PageLayout from './pageLayout';


class Summary extends React.Component {
    constructor(props) {
        super(props)
        this.chart = {}
    }


    render() {
        this.chart = this.props.data.chart
        this.pieChart = this.props.data.pieChart
        this.type = this.props.type
        this.pieChart1 = {
            ...this.pieChart,
            labels: this.pieChart && [...this.pieChart.labels.slice(0, 1)]
        }
        this.pieChart2 = {
            ...this.pieChart,
            labels: this.pieChart && [...this.pieChart.labels.slice(1, 2)]
        }
        this.pieChart3 = {
            ...this.pieChart,
            labels: this.pieChart && [...this.pieChart.labels.slice(2, 3)]
        }
        this.pieChart4 = {
            ...this.pieChart,
            labels: this.pieChart && [...this.pieChart.labels.slice(3, 4)]
        }
        this.pieChart5 = {
            ...this.pieChart,
            labels: this.pieChart && [...this.pieChart.labels.slice(4, 5)]
        }
        return (

            <PageLayout>
                <div className="col-sm-12">
                    {
                        this.pieChart &&
                        <div className="mt-2" style={{ backgroundColor: "#dbe8ec" }}>
                            <div className="p-2" style={{ backgroundColor: "#ffffff" }}>
                                <div className="row">

                                    <div className="col-12">

                                        {/* Responsive wrapper:
                            - stacks vertically on xs (flex-column)
                            - lays out horizontally on md+ (flex-row)
                        */}
                                        <div className="d-flex flex-column flex-md-row align-items-center justify-content-center"
                                            style={{ minHeight: '300px', gap: '1rem' }}>

                                            {/* Left legends */}
                                            <div className="d-flex w-100 w-md-auto justify-content-center justify-content-md-start"
                                                style={{ maxWidth: 240 }}>
                                                <div className="d-flex flex-row flex-md-column align-items-center gap-2">
                                                    <PieChartLegends pieChart={this.pieChart1} />
                                                   <PieChartLegends pieChart={this.pieChart5} />
                                                </div>
                                            </div>

                                            {/* Chart - grows in the middle and stays responsive */}
                                            <div className="d-flex flex-fill justify-content-center align-items-center"
                                                style={{ width: '100%', maxWidth: 640 }}>
                                                <div style={{ width: '100%' }}>
                                                    <ReChart data={this.pieChart.data} innerData={this.pieChart.innerData} />
                                                </div>
                                            </div>

                                            {/* Right legends */}
                                            <div className="d-flex w-100 w-md-auto justify-content-center justify-content-md-end"
                                                style={{ maxWidth: 240 }}>
                                                <div className="d-flex flex-row flex-md-column align-items-center gap-2">
                                                    <PieChartLegends pieChart={this.pieChart3} />
                                                                                                    
                                                      <PieChartLegends pieChart={this.pieChart4} />
                                                       <PieChartLegends pieChart={this.pieChart2} />

                                                </div>
                                            </div>

                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="row">
                                <div className="col-12">
                                    <Points points={this.props.data.points} />
                                </div>
                            </div>

                        </div>
                    }
                </div>
            </PageLayout>

        )

    }
}

export default Summary